window.KH_SURA(49, {"sura": "الحجرات", "n": 49, "ayat": {"1": "يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تُقَدِّمُوا بَيْنَ يَدَيِ اللَّهِ وَرَسُولِهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ", "2": "يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلَا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَنْ تَحْبَطَ أَعْمَالُكُمْ وَأَنْتُمْ لَا تَشْعُرُونَ", "3": "إِنَّ الَّذِينَ يَغُضُّونَ أَصْوَاتَهُمْ عِنْدَ رَسُولِ اللَّهِ أُولَئِكَ الَّذِينَ امْتَحَنَ اللَّهُ قُلُوبَهُمْ لِلتَّقْوَى لَهُمْ مَغْفِرَةٌ وَأَجْرٌ عَظِيمٌ", "4": "إِنَّ الَّذِينَ يُنَادُونَكَ مِنْ وَرَاءِ الْحُجُرَاتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ", "5": "وَلَوْ أَنَّهُمْ صَبَرُوا حَتَّى تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَهُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ", "6": "يَاأَيُّهَا الَّذِينَ آمَنُوا إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا أَنْ تُصِيبُوا قَوْمًا بِجَهَالَةٍ فَتُصْبِحُوا عَلَى مَا فَعَلْتُمْ نَادِمِينَ", "7": "وَاعْلَمُوا أَنَّ فِيكُمْ رَسُولَ اللَّهِ لَوْ يُطِيعُكُمْ فِي كَثِيرٍ مِنَ الْأَمْرِ لَعَنِتُّمْ وَلَكِنَّ اللَّهَ حَبَّبَ إِلَيْكُمُ الْإِيمَانَ وَزَيَّنَهُ فِي قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ أُولَئِكَ هُمُ الرَّاشِدُونَ", "8": "فَضْلًا مِنَ اللَّهِ وَنِعْمَةً وَاللَّهُ عَلِيمٌ حَكِيمٌ", "9": "وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا فَإِنْ بَغَتْ إِحْدَاهُمَا عَلَى الْأُخْرَى فَقَاتِلُوا الَّتِي تَبْغِي حَتَّى تَفِيءَ إِلَى أَمْرِ اللَّهِ فَإِنْ فَاءَتْ فَأَصْلِحُوا بَيْنَهُمَا بِالْعَدْلِ وَأَقْسِطُوا إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ", "10": "إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُرْحَمُونَ", "11": "يَاأَيُّهَا الَّذِينَ آمَنُوا لَا يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ عَسَى أَنْ يَكُونُوا خَيْرًا مِنْهُمْ وَلَا نِسَاءٌ مِنْ نِسَاءٍ عَسَى أَنْ يَكُنَّ خَيْرًا مِنْهُنَّ وَلَا تَلْمِزُوا أَنْفُسَكُمْ وَلَا تَنَابَزُوا بِالْأَلْقَابِ بِئْسَ الِاسْمُ الْفُسُوقُ بَعْدَ الْإِيمَانِ وَمَنْ لَمْ يَتُبْ فَأُولَئِكَ هُمُ الظَّالِمُونَ", "12": "يَاأَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَنْ يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ تَوَّابٌ رَحِيمٌ", "13": "يَاأَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ", "14": "قَالَتِ الْأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا وَلَمَّا يَدْخُلِ الْإِيمَانُ فِي قُلُوبِكُمْ وَإِنْ تُطِيعُوا اللَّهَ وَرَسُولَهُ لَا يَلِتْكُمْ مِنْ أَعْمَالِكُمْ شَيْئًا إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ", "15": "إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ ثُمَّ لَمْ يَرْتَابُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللَّهِ أُولَئِكَ هُمُ الصَّادِقُونَ", "16": "قُلْ أَتُعَلِّمُونَ اللَّهَ بِدِينِكُمْ وَاللَّهُ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ", "17": "يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا قُلْ لَا تَمُنُّوا عَلَيَّ إِسْلَامَكُمْ بَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَاكُمْ لِلْإِيمَانِ إِنْ كُنْتُمْ صَادِقِينَ", "18": "إِنَّ اللَّهَ يَعْلَمُ غَيْبَ السَّمَاوَاتِ وَالْأَرْضِ وَاللَّهُ بَصِيرٌ بِمَا تَعْمَلُونَ"}, "units": [{"aya": 1, "title": "قراءة قوله تعالى: {لا تقدموا}", "mawsua": {"taliq": 6083, "masala": "قراءة قوله تعالى: {لا تقدموا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "بضم التاء، وكسر الدال، هكذا {تقدموا}", "ashab": "", "athar": []}, {"n": 2, "t": "بفتح التاء والدال، هكذا «تقدموا»، بمعنى: لا تتقدموا", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6083, "mi": 1, "aya": 1, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 6", "qawl": "الأول", "nass": "المعنى على ضم التاء: بين يدي قول الله ورسوله", "qawaid": [], "tabi": ""}, {"taliq": 6083, "mi": 1, "aya": 1, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 337", "qawl": "الأول", "nass": "وبضم التاء من قوله: {لا تقدموا} قرأ قراء الأمصار، وهي القراءة التي لا أستجيز القراءة بخلافها؛ لإجماع الحجة من القراء عليها، وقد حكي عن العرب: قدمت في كذا، وتقدمت في كذا. فعلى هذه اللغة لو كان قيل: «لا تقدموا", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 2, "title": "في معنى ذلك ﴿أن تحبط أعمالكم﴾", "tabari": {"page": "21/343", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: لا تحبط أعمالكم. قال: وفيه الجزم والرفع إذا وضعت \"لا\" مكان \"أن\". قال: وهي في قراءة عبد الله: (فتحبط أعمالكم). [وهو دليل على جواز الجزم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "قال: ﴿أن تحبط أعمالكم﴾] . أي مخافة أن تحبط أعمالكم. وقد يقال: أسند الحائط أن يميل", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "في السخرية التي نهى الله المؤمنين عنها في هذه الآية", "tabari": {"page": "21/364", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندنا أن يقال: إن الله عم بنهيه المؤمنين أن يسخر بعضهم من بعض جميع معاني السخرية، فلا يحل لمؤمن أن يسخر من مؤمن لا لفقره، ولا لذنب ركبه، ولا لغير ذلك.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هي سخرية الغني من الفقير، نهي أن يسخر من الفقير لفقره", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل ذلك نهي من الله من ستر عليه من أهل الإيمان، أن يسخر ممن كشف في الدنيا ستره منهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [71705, 71728, 71732, 71734]}]}, "mawaqif": [{"taliq": 6096, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "21/ 366", "qawl": "العموم", "nass": "الصواب من القول في ذلك عندي أن يقال: إن الله عم بنهيه المؤمنين عن أن يسخر بعضهم من بعض جميع معاني السخرية، فلا يحل لمؤمن أن يسخر من مؤمن لا لفقره، ولا لذنب ركبه، ولا لغير ذلك", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 6096, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 15", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 1, "imgs": ["049_001_1.png"], "pages": [477], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 6096, "masala": "السخرية المنهي عنها", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها استهزاء الغني بالفقير لفقره", "ashab": "", "athar": []}, {"n": 2, "t": "أنها استهزاء المسلم بمن أعلن فسقه", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "قال بـالعموم"], ["ابن عطية", "قال بـالعموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 11, "title": "في الألقاب التي نهى الله عن التنابز بها في هذه الآية", "tabari": {"page": "21/367", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عني بها الألقاب التي يكره النبز بها الملقب. وقالوا: إنما نزلت هذه الآية في قوم كانت لهم أسماء في الجاهلية، فلما أسلموا نهوا أن يدعو بعضهم بعضا بما يكره من أسمائه التي كان يدعى بها في الجاهلية", "taqdim": 0, "n_athar": 4, "qailun": [["عامر", "تابعي"], ["أبي جبيرة بن الضحاك", ""]], "athar": [71715]}, {"n": 2, "t": "بل ذلك قول الرجل المسلم للرجل المسلم: يا فاسق، يا زاني", "taqdim": 0, "n_athar": 8, "qailun": [["حصين", ""], ["عكرمة", "تابعي"], ["مجاهد و عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [71703, 71705, 71708, 71710, 71721, 71726, 71728, 71732, 71734]}, {"n": 3, "t": "بل ذلك تسمية الرجل الرجل بالكفر بعد الإسلام، وبالفسوق و الأعمال القبيحة بعد التوبة", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["معمر", "تابع التابعين"]], "athar": [71697, 71699, 71707, 71713, 71714, 71719]}]}, "mawaqif": [{"taliq": 6098, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "21/ 371", "qawl": "العموم", "nass": "والذي هو أولى الأقوال في تأويل ذلك عندي بالصواب أن يقال: إن الله -تعالى ذكره- نهى المؤمنين أن يتنابزوا بالألقاب، والتنابز بالألقاب: هو دعاء المرء صاحبه بما يكرهه من اسم أو صفة، وعم الله بنهيه ذلك، ولم يخصص به بعض الألقاب دون بعض، فغير جائز لأحد من المسلمين أن ينبز أخاه باسم يكرهه أو صفة يكرهها، وإذا كان ذلك كذلك صحت الأقوال التي قالها أهل التأويل في ذلك التي ذكرناها كلها، ولم يكن بعض ذلك أولى بالصواب من بعض؛ لأن كل ذلك مما نهى الله المسلمين أن ينبز بعضهم بعضا به", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 6098, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 17", "qawl": "", "nass": "وليس من هذا قول المحدثين: سليمان الأعمش، وواصل الأحدب، ونحوه مما تدعو الضرورة إليه، وليس فيه قصد استخفاف ولا أذى", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["049_002_1.png"], "pages": [477], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 6098, "masala": "الألقاب التي نهى الله عن التنابز بها", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن المراد: الألقاب التي يكره صاحبها أن يدعى بها", "ashab": "", "athar": []}, {"n": 2, "t": "أن المراد: تسمية الرجل بالأعمال السيئة بعد إسلامه وتوبته منها، ك: يا فاسق، ويا سارق، ويا زان", "ashab": "", "athar": []}, {"n": 3, "t": "أن المراد: تسمية الرجل باسم دينه الذي كان عليه قبل الإسلام، ك: يا يهودي، ويا نصراني", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "قال بـالعموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 11, "title": "قوله تعالى: {بئس الاسم الفسوق بعد الإيمان}", "mawsua": {"taliq": 6099, "masala": "قوله تعالى: {بئس الاسم الفسوق بعد الإيمان}", "sigha": "احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "بئس اسم تكتسبونه بعصيانكم ونبزكم بالألقاب فتكونون فساقا بالمعصية بعد إيمانكم", "ashab": "", "athar": []}, {"n": 2, "t": "بئس ما يقول الرجل لأخيه: يا فاسق بعد إيمانه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6099, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 18", "qawl": "", "nass": "قوله تعالى: {بئس الاسم الفسوق بعد الإيمان} يحتمل معنيين: أحدهما: بئس اسم تكتسبونه بعصيانكم ونبزكم بالألقاب فتكونون فساقا بالمعصية بعد إيمانكم. والثاني: بئس ما يقول الرجل لأخيه: يا فاسق بعد إيمانه", "qawaid": [], "tabi": ""}, {"taliq": 6099, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "21/ 372", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6099, "mi": 1, "aya": 11, "alam": "ابن تيمية", "fil": "ذهب", "kind": "قول", "ref": "6/ 75", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 6099, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "", "qawl": "الأول", "nass": "", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 6099, "mi": 1, "aya": 11, "alam": "ابن تيمية", "fil": "انتقد", "kind": "نقد", "ref": "3/ 9", "qawl": "الثاني", "nass": "قيل: معناه: لا تسميه فاسقا ولا كافرا بعد إيمانه. وهذا ضعيف، بل المراد: بئس الاسم أن تكونوا فساقا بعد إيمانكم، كما قال تعالى في الذي كذب: {إن جاءكم فاسق بنبإ فتبينوا} فسماه فاسقا، وفي الصحيحين عن النبي صلى الله عليه وسلم أنه قال: «سباب المسلم فسوق، وقتاله كفر", "qawaid": ["القرآن والنظائر", "السنة"], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "q"], ["ابن تيمية", "q"]], "2": [["ابن تيمية", "d"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {"ابن تيمية": ["القرآن والنظائر", "السنة"]}}}, {"aya": 13, "title": "تأويل: ﴿وجعلناكم شعوبا وقبائل لتعارفوا﴾", "tabari": {"page": "21/385", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وجعلناكم شعوبا وقبائل لتعارفوا﴾. يقول: وجعلناكم متناسبين؛ فبعضكم يناسب بعضا نسبا بعيدا، وبعضكم يناسب بعضا نسبا قريبا، فالمتناسب النسب البعيد من ناسبه أهل الشعوب، وذلك أنه إذا قيل للرجل من العرب: من أي شعب أنت؟ قال: أنا من مضر. أو : ربيعة. وأما أهل المناسبة القريبة فأهل القبائل؛ وهم كتميم من مضر، وبكر من ربيعة، وأقرب من (٥) القبائل الأفخاذ؛ وهما كشيبان من بكر، ودارم من تميم، ونحو ذلك، ومن الشعب قو", "taqdim": 1, "n_athar": 7, "qailun": [["ابن عباس", "صحابي"], ["سعيد بن جبير", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [71792, 71798, 71801, 71802, 71803, 71804, 71807, 71808, 71809, 71813, 71819, 71821, 71824, 71833, 71834]}, {"n": 2, "t": "الشعوب الأفخاذ", "taqdim": 0, "n_athar": 1, "qailun": [["سعيد بن جبير", "تابعي"]], "athar": [71807, 71808]}, {"n": 3, "t": "الشعوب البطون، والقبائل الأفخاذ", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [71792, 71801, 71802, 71803, 71804, 71819, 71824, 71833, 71834]}, {"n": 4, "t": "الشعوب الأنساب", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [71792, 71801, 71802, 71803, 71804, 71819, 71824, 71833, 71834]}]}, "mawaqif": [{"taliq": 6108, "mi": 0, "aya": 13, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "21/ 386 - 387", "qawl": "", "nass": "يقول -تعالى ذكره-: إن أكرمكم -أيها الناس- عند ربكم أشدكم اتقاء له بأداء فرائضه واجتناب معاصيه، لا أعظمكم بيتا، ولا أكثركم عشيرة", "qawaid": ["أقوال السلف"], "tabi": ""}], "mushid": {"i": 3, "imgs": ["049_003_1.png", "049_003_2.png"], "pages": [477, 478], "n": 4, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["أقوال السلف"]}, "rulesD": {}}}, {"aya": 14, "title": "في السبب الذي من أجله قيل للنبي ﷺ: قل لهؤلاء الأعراب: [قولوا: أسلمنا] ، ولا تقولوا: آمنا", "tabari": {"page": "21/388", "sarih": 1, "tarjih": "وأولى الأقوال بالصواب في تأويل ذلك القول الذي ذكرناه عن الزهري، وهو أن الله تقدم إلى هؤلاء الأعراب الذين دخلوا في الملة إقرارا منهم بالقول، ولم يحققوا قولهم بعملهم أن يقولوا بالإطلاق: آمنا. دون تقييد قولهم ذلك بأن يقولوا: آمنا بالله ورسوله. ولكن أمرهم أن يقولوا القول الذي لا يشكل على سامعيه، والذي قائله فيه محق، وهو أن يقولوا: أسلمنا. بمعنى: دخلنا في الملة، [وحقنا الدماء] والأموال، بشهادة الحق.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "إنما أمر النبي ﷺ بذلك؛ لأن القوم كانوا صدقوا بألسنتهم، ولم يصدقوا قولهم بفعلهم، فقيل لهم: قولوا: أسلمنا؛ لأن الإسلام قول، والإيمان قول وعمل", "taqdim": 0, "n_athar": 4, "qailun": [["الزهري", "تابعي"], ["سعد", "صحابي"], ["ابن زيد", "تابع التابعين"], ["إبراهيم", "تابعي"]], "athar": [71851, 71852, 71853, 71854, 71868]}, {"n": 2, "t": "إنما أمر الله ﷿ النبي ﷺ بقيل ذلك لهم؛ لأنهم أرادوا أن يتسموا بأسماء المهاجرين قبل أن يهاجروا، فأعلمهم الله أن لهم أسماء الأعراب، لا أسماء المهاجرين", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [71841, 71862]}, {"n": 3, "t": "قيل ذلك لهم؛ لأنهم منوا على رسول الله ﷺ بإسلامهم، فقال الله لنبيه ﷺ: قل لهم: لم تؤمنوا، ولكن استسلمتم خوف السباء والقتل", "taqdim": 0, "n_athar": 5, "qailun": [["قتادة", "تابعي"], ["سعيد بن جبير", "تابعي"], ["مجاهد", "تابعي"]], "athar": [71836, 71837, 71838, 71842, 71844, 71846, 71847, 71858, 71863, 71864, 71865]}]}, "mawaqif": [{"taliq": 6112, "mi": 1, "aya": 14, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 175", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6112, "mi": 1, "aya": 14, "alam": "ابن جرير", "fil": "اختاره", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6112, "mi": 1, "aya": 14, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 392", "qawl": "الأول", "nass": "", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": ""}, {"taliq": 6112, "mi": 1, "aya": 14, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الأول", "nass": "", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": "ابن جرير"}, {"taliq": 6112, "mi": 1, "aya": 14, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "وأولى الأقوال بالصواب في تأويل ذلك القول الذي ذكرناه عن الزهري، وهو أن الله تقدم إلى هؤلاء الأعراب الذين دخلوا في الملة إقرارا منهم بالقول، ولم يحققوا قولهم بعملهم أن يقولوا بالإطلاق: آمنا. دون تقييد قولهم بذلك بأن يقولوا: آمنا بالله ورسوله. ولكن أمرهم أن يقولوا القول الذي لا يشكل على سامعيه، والذي قائله فيه محق، وهو أن يقولوا: أسلمنا. بمعنى: دخلنا في الملة، وحقنا الدماء والأموال، بشهادة الحق", "qawaid": [], "tabi": ""}, {"taliq": 6112, "mi": 1, "aya": 14, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 175", "qawl": "", "nass": "الصحيح الأول، أنهم قوم ادعوا لأنفسهم مقام الإيمان، ولم يحصل لهم بعد، فأدبوا وأعلموا أن ذلك لم يصلوا إليه بعد، ولو كانوا منافقين لعنفوا وفضحوا كما ذكر المنافقون في سورة براءة، وإنما قيل لهؤلاء تأديبا: {قل لم تؤمنوا ولكن قولوا أسلمنا ولما يدخل الإيمان في قلوبكم} أي: لم تصلوا إلى حقيقة الإيمان بعد", "qawaid": [], "tabi": ""}, {"taliq": 6112, "mi": 1, "aya": 14, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 71 - 75", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن كثير"}], "mushid": {"i": 4, "imgs": ["049_004_1.png"], "pages": [478], "n": 2, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 6112, "masala": "السبب الذي من أجله قيل للنبي صلى الله عليه وسلم: قل لهؤلاء الأعراب: قولوا أسلمنا، ولا تقولوا آمنا", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه أمر صلى الله عليه وسلم بذلك لأن القوم كانوا صدقوا بألسنتهم، ولم يصدقوا قولهم بفعلهم، فقيل لهم: قولوا أسلمنا؛ لأن الإسلام قول، والإيمان قول وعمل", "ashab": "", "athar": []}, {"n": 2, "t": "أنه أمر صلى الله عليه وسلم بذلك لأنهم أرادوا أن يتسموا بأسماء المهاجرين قبل أن يهاجروا، فأعلمهم الله أن لهم أسماء الأعراب، لا أسماء المهاجرين", "ashab": "", "athar": []}, {"n": 3, "t": "أنه أمر صلى الله عليه وسلم بذلك لأن القوم منوا على رسول الله صلى الله عليه وسلم بإسلامهم، فقال الله لنبيه صلى الله عليه وسلم: قل لهم لم تؤمنوا، ولكن استسلمتم خوف السباء والقتل", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"], ["ابن تيمية", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"], ["ابن تيمية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "ابن كثير": ["ظاهر الآية ولفظها", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 14, "title": "قراءة قوله تعالى: {يلتكم}", "mawsua": {"taliq": 6113, "masala": "قراءة قوله تعالى: {يلتكم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "بغير همز ولا ألف، هكذا {يلتكم}، من: لات يليت، بمعنى: نقص. وهي قراءة الجمهور", "ashab": "", "athar": []}, {"n": 2, "t": "بهمزة وألف، هكذا «يألتكم»، من: ألت يألت، بمعنى: لات", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6113, "mi": 1, "aya": 14, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "", "qawl": "الثاني", "nass": "اعتبارا منه في ذلك بقوله: {وما ألتناهم من عملهم من شيء} [الطور: 21]", "qawaid": [], "tabi": ""}, {"taliq": 6113, "mi": 1, "aya": 14, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 394", "qawl": "الأول", "nass": "والصواب من القراءة عندنا في ذلك ما عليه قراء المدينة والكوفة: {لا يلتكم} بغير ألف ولا همز، على لغة من قال: لات يليت؛ لعلتين: إحداهما: إجماع الحجة من القراء عليها. والثانية: أنها في المصحف بغير ألف، ولا تسقط الهمزة في مثل هذا الموضع؛ لأنها ساكنة، والهمزة إذا سكنت ثبتت، كما يقال: تأمرون وتأكلون، وإنما تسقط إذا سكن ما قبلها. ولا يحمل حرف في القرآن إذا أتى بلغة على آخر جاء بلغة خلافها إذا كانت اللغتان معروفتين في كلام العرب، وقد ذكرنا أن ألت ولات لغتان معروفتان من كلامهم", "qawaid": ["القراءة ورسم المصحف", "القراءة ورسم المصحف", "اللغة"], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["القراءة ورسم المصحف", "اللغة"]}, "rulesD": {}}}], "extra": [], "others": {"0": [{"id": 6082, "kinds": "نقل", "text": "نقل ابنُ عطية (8/ 5) الإجماعَ على مدنية سورة الحجرات، فقال: «هي مدنية بإجماع من أهل التأويل».\nوقد نُصَّ على مدنية السورة أيضًا في تفسير ابن كثير (13/ 136).", "mawaqif": [{"taliq": 6082, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "8/ 5", "qawl": "", "nass": "هي مدنية بإجماع من أهل التأويل", "qawaid": [], "tabi": ""}]}], "1": [{"id": 6084, "kinds": "نقل", "text": "ذكر ابنُ عطية (8/ 6) هذه الرواية، ثم قال: «وذهب بعض قائلي هذه المقالة إلى أن قوله: {لا تقدموا} معناه: لا تُقَدِّموا وُلاة، فهو من تقدّم الأمراء، وعموم اللفظ أحسن، أي: اجعلوه مبدأ في الأقوال والأفعال».", "mawaqif": [{"taliq": 6084, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 6", "qawl": "", "nass": "وذهب بعض قائلي هذه المقالة إلى أن قوله: {لا تقدموا} معناه: لا تقدموا ولاة، فهو من تقدم الأمراء، وعموم اللفظ أحسن، أي: اجعلوه مبدأ في الأقوال والأفعال", "qawaid": [], "tabi": ""}]}, {"id": 6085, "kinds": "غيره", "text": "قال ابن عطية (8/ 5): «كانت عادة العرب -وهي إلى الآن- الاشتراك في الآراء، وأن يتكلّم كلٌّ بما شاء ويفعل ما أحب، فمشى بعض الناس ممن لم تتمرّن نفسه مع النبي صلى الله عليه وسلم على بعض ذلك، قال قتادة: فربما قال قوم: لو نزل كذا وكذا في معنى كذا وكذا، وينبغي أن يكون كذا. وأيضًا فإنّ قومًا ذبحوا ضحاياهم قبل النبي صلى الله عليه وسلم، حكاه الحسن بن أبي الحسن، وقومًا فعلوا في بعض حروبه وغزواته أشياء بآرائهم، فنَزَلتْ هذه الآية ناهيةً عن جميع ذلك».", "mawaqif": [{"taliq": 6085, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 5", "qawl": "", "nass": "كانت عادة العرب -وهي إلى الآن- الاشتراك في الآراء، وأن يتكلم كل بما شاء ويفعل ما أحب، فمشى بعض الناس ممن لم تتمرن نفسه مع النبي صلى الله عليه وسلم على بعض ذلك، قال قتادة: فربما قال قوم: لو نزل كذا وكذا في معنى كذا وكذا، وينبغي أن يكون كذا. وأيضا فإن قوما ذبحوا ضحاياهم قبل النبي صلى الله عليه وسلم، حكاه الحسن بن أبي الحسن، وقوما فعلوا في بعض حروبه وغزواته أشياء بآرائهم، فنزلت هذه الآية ناهية عن جميع ذلك", "qawaid": [], "tabi": ""}]}], "2": [{"id": 6086, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 520): «روي أن سببها كلام أبي بكر وعمر رضي الله عنهما المتقدم في أمر الأقرع والقعقاع، والصحيح أنها نَزَلتْ بسبب عادة الأعراب مِن الجفاء، وعلو الصوت، والعُنجهيَّة». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 6086, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 520", "qawl": "", "nass": "روي أن سببها كلام أبي بكر وعمر رضي الله عنهما المتقدم في أمر الأقرع والقعقاع، والصحيح أنها نزلت بسبب عادة الأعراب من الجفاء، وعلو الصوت، والعنجهية", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 6087, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 8): «قوله تعالى: {أن تحبط} مفعول من أجله، أي: مخافة أن تحبط. والحبط: إفساد العمل بعد تقرره، يقال: حبِط -بكسر الباء-، وأحبطه الله، وهذا الحبط إن كانت الآية معرِّضة بمن يفعل ذلك استخفافًا واستحقارًا وجرأةً فذلك كفر، والحبط معه على حقيقته. وإن كان التعريض للمؤمن الفاضل الذي يفعل ذلك غفلةً وجريًا على طبْعه، فإنما يحبط عمله البرَّ في توقير النبي صلى الله عليه وسلم وغضّ الصوت عنده إن لو فعل ذلك، فكأنه قال: أن تحبط الأعمال التي هي معدَّة أن تعملوها فتؤجروا عليها. ويحتمل أن يكون المعنى: أن تأثموا ويكون ذلك سببًا إلى الوحشة في نفوسكم، فلا تزال معتقداتكم تتجرد القهقرى حتى يؤول ذلك إلى الكفر فيُحبط الأعمالَ حقيقة. وظاهر الآية أنها مخاطبة لفضلاء المؤمنين الذين لا يفعلون ذلك احتقارًا، وذلك أنه لا يقال لمنافق يعمل ذلك جرأة: وأنت لا تشعر. لأنه ليس له عمل يعتقده هو عملًا».", "mawaqif": [{"taliq": 6087, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 8", "qawl": "", "nass": "قوله تعالى: {أن تحبط} مفعول من أجله، أي: مخافة أن تحبط. والحبط: إفساد العمل بعد تقرره، يقال: حبط -بكسر الباء-، وأحبطه الله، وهذا الحبط إن كانت الآية معرضة بمن يفعل ذلك استخفافا واستحقارا وجرأة فذلك كفر، والحبط معه على حقيقته. وإن كان التعريض للمؤمن الفاضل الذي يفعل ذلك غفلة وجريا على طبعه، فإنما يحبط عمله البر في توقير النبي صلى الله عليه وسلم وغض الصوت عنده إن لو فعل ذلك، فكأنه قال: أن تحبط الأعمال التي هي معدة أن تعملوها فتؤجروا عليها. ويحتمل أن يكون المعنى: أن تأثموا ويكون ذلك سببا إلى الوحشة في نفوسكم، فلا تزال معتقداتكم تتجرد القهقرى حتى يؤول ذلك إلى الكفر فيحبط الأعمال حقيقة. وظاهر الآية أنها مخاطبة لفضلاء المؤمنين الذين لا يفعلون ذلك احتقارا، وذلك أنه لا يقال لمنافق يعمل ذلك جرأة: وأنت لا تشعر. لأنه ليس له عمل يعتقده هو عملا", "qawaid": [], "tabi": ""}]}], "3": [{"id": 6088, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 9): «مَن غلب شهوتَه وغضبَه فذلك الذي امتحن الله قلبه للتقوى، وبذلك تكون الاستقامة».", "mawaqif": [{"taliq": 6088, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 9", "qawl": "", "nass": "من غلب شهوته وغضبه فذلك الذي امتحن الله قلبه للتقوى، وبذلك تكون الاستقامة", "qawaid": [], "tabi": ""}]}], "6": [{"id": 6089, "kinds": "خلاف،نقد", "text": "قال ابنُ القيم (3/ 6 - 7): «هاهنا فائدة لطيفة، وهي أنه سبحانه لم يأمر بردّ خبر الفاسق وتكذيبه وردّ شهادته جملة، وإنما أمر بالتبيّن، فإن قامت قرائن وأدلة مِن خارجٍ تدل على صدقه عُمِل بدليل الصدق، ولو أخبر به مَن أخبر، فهكذا ينبغي الاعتماد في رواية الفاسق وشهادته، وكثير من الفاسقين يصدُقون في أخبارهم ورواياتهم وشهاداتهم، بل كثير منهم يتحرّى الصدق غاية التحري، وفِسْقه من جهات أُخر، فمثل هذا لا يُردّ خبره ولا شهادته، ولو رُدّت شهادة مثل هذا وروايته لتعطّلت أكثر الحقوق، وبطل كثير من الأخبار الصحيحة، ولاسيما مَن فِسْقه مِن جهة الاعتقاد والرأي، وهو متحرٍّ للصدق، فهذا لا يُردّ خبره ولا شهادته. وأمّا مَن فِسْقه مِن جهة الكذب فإن كثر منه وتكرر بحيث يغلب كذبه على صدقه، فهذا لا يُقبل خبره ولا شهادته، وإن ندر منه مرة ومرتين ففي ردّ شهادته وخبره بذلك قولان للعلماء، وهما روايتان عن الإمام أحمد».\nوبنحوه قال ابنُ تيمية (6/ 46 - 47).", "mawaqif": [{"taliq": 6089, "mi": 0, "aya": 6, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "3/ 6 - 7", "qawl": "", "nass": "هاهنا فائدة لطيفة، وهي أنه سبحانه لم يأمر برد خبر الفاسق وتكذيبه ورد شهادته جملة، وإنما أمر بالتبين، فإن قامت قرائن وأدلة من خارج تدل على صدقه عمل بدليل الصدق، ولو أخبر به من أخبر، فهكذا ينبغي الاعتماد في رواية الفاسق وشهادته، وكثير من الفاسقين يصدقون في أخبارهم ورواياتهم وشهاداتهم، بل كثير منهم يتحرى الصدق غاية التحري، وفسقه من جهات أخر، فمثل هذا لا يرد خبره ولا شهادته، ولو ردت شهادة مثل هذا وروايته لتعطلت أكثر الحقوق، وبطل كثير من الأخبار الصحيحة، ولاسيما من فسقه من جهة الاعتقاد والرأي، وهو متحر للصدق، فهذا لا يرد خبره ولا شهادته. وأما من فسقه من جهة الكذب فإن كثر منه وتكرر بحيث يغلب كذبه على صدقه، فهذا لا يقبل خبره ولا شهادته، وإن ندر منه مرة ومرتين ففي رد شهادته وخبره بذلك قولان للعلماء، وهما روايتان عن الإمام أحمد", "qawaid": [], "tabi": ""}, {"taliq": 6089, "mi": 0, "aya": 6, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 46 - 47", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن القيم"}]}, {"id": 6090, "kinds": "تعليق،نقل", "text": "قال ابنُ عطية (8/ 11): «الفسق: الخروج عن نهج الحق، وهو مراتب متباينة، كلّها مظنّة للكذب وموضع تثبت وتبين، وتأنس القائلون بقبول خبر الواحد بما يقتضيه دليل خطاب هذه الآية؛ لأنه يقتضي أنّ غير الفاسق إذا جاء بنبإ أن يعمل بحسبه، وهذا ليس باستدلال قوي».\nونقل أنّ منذر بن سعيد قال: هذه الآية تردُّ على مَن قال: إنّ المسلمين كلّهم عدول حتى تثبت الجرحة؛ لأن الله تعالى أمر بالتبيّن قبل القبول. ثم علَّق (8/ 12) بقوله: «وقوله يقتضي أن المجهول الحال يُخشى أن يكون فاسقًا، والاحتياط لازم».", "mawaqif": [{"taliq": 6090, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 11", "qawl": "", "nass": "الفسق: الخروج عن نهج الحق، وهو مراتب متباينة، كلها مظنة للكذب وموضع تثبت وتبين، وتأنس القائلون بقبول خبر الواحد بما يقتضيه دليل خطاب هذه الآية؛ لأنه يقتضي أن غير الفاسق إذا جاء بنبإ أن يعمل بحسبه، وهذا ليس باستدلال قوي", "qawaid": [], "tabi": ""}]}], "9": [{"id": 6091, "kinds": "بيان،نقل", "text": "أشار ابنُ تيمية (6/ 52) إلى أنّ عائشة رضي الله عنها قالت هذا لَمّا وقعت الفتنة بين الصحابة رضي الله عنهم.", "mawaqif": [{"taliq": 6091, "mi": 0, "aya": 9, "alam": "ابن تيمية", "fil": "أشار", "kind": "نقل", "ref": "6/ 52", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "10": [{"id": 6092, "kinds": "نقد،بيان،نقل", "text": "ذَهَبَ ابنُ جرير (21/ 363 - 364) إلى قراءة التثنية، واستدرك على قراءة ابن سيرين، فقال: «معنى الأخوين في هذا الموضع: كل مقتتلين من أهل الإيمان، وبالتثنية قرأ ذلك قراء الأمصار، وذكر عن ابن سيرين أنه قرأ: (بَيْنَ إخْوانِكُمْ) بالنون على مذهب الجمع، وذلك من جهة العربية صحيح، غير أنه خلاف لما عليه قراء الأمصار، فلا أحبّ القراءة بها».", "mawaqif": [{"taliq": 6092, "mi": 0, "aya": 10, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "21/ 363 - 364", "qawl": "", "nass": "معنى الأخوين في هذا الموضع: كل مقتتلين من أهل الإيمان، وبالتثنية قرأ ذلك قراء الأمصار، وذكر عن ابن سيرين أنه قرأ: (بين إخوانكم) بالنون على مذهب الجمع، وذلك من جهة العربية صحيح، غير أنه خلاف لما عليه قراء الأمصار، فلا أحب القراءة بها", "qawaid": [], "tabi": ""}]}, {"id": 6093, "kinds": "تعليق", "text": "عَلَّقَ ابنُ عطية (8/ 14 بتصرف) على قراءة الجمع هذه بقوله: «هي حسنة؛ لأن الأكثر من جمع» الأخ «في الدّين، ونحوه من غير النسب:» إخوان «، والأكثر من النسب:» إخْوَة «و» آخاء « … ، وقد تتداخل هذه الجموع، وكلها في كتاب الله، فمنه: {إنما المؤمنون إخوة}، ومنه: {أو بيوت إخوانكم} [النور: 61]، فهذا جاء على الأقل في الاستعمال».", "mawaqif": [{"taliq": 6093, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 14 بتصرف", "qawl": "", "nass": "هي حسنة؛ لأن الأكثر من جمع", "qawaid": [], "tabi": ""}]}, {"id": 6094, "kinds": "بيان،تعليق", "text": "عَلَّقَ ابنُ عطية (8/ 14) على قراءة التثنية، بقوله: «ذلك رعاية لحال أقل عدد يقع فيه القتال والتشاجر، والجماعة متى قصدوا الإصلاح فإنما هو بين رجلين رجلين».", "mawaqif": [{"taliq": 6094, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 14", "qawl": "", "nass": "ذلك رعاية لحال أقل عدد يقع فيه القتال والتشاجر، والجماعة متى قصدوا الإصلاح فإنما هو بين رجلين رجلين", "qawaid": [], "tabi": ""}]}], "11": [{"id": 6095, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 15 بتصرف): «هذه الآيات والتي بعدها نَزَلتْ في خُلق أهل الجاهلية، وذلك لأنهم كانوا يَجرون مع شهوات نفوسهم، لم يُقَوِّمهم أمْرٌ مِن الله ولا نهيٌ، فكان الرجل يسخر، ويهمز، ويلمز، وينبز بالألقاب، ويظنّ الظّنون فيتكلّم بها، ويغتاب، ويفتخر بنَسَبه، إلى غير ذلك مِن أخلاق النفوس البطّالة، فنَزَلتْ هذه الآية تأديبًا لأمة محمد صلى الله عليه وسلم. وذكر بعض الناس لهذه الآيات أسبابًا … ، والقويُّ عندي أنّ هذه الآية نَزَلتْ تقويمًا كسائر أمر الشرع، ولو تتبِّعت الأسباب لكانت أكثر من أنْ تُحصى».", "mawaqif": [{"taliq": 6095, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 15 بتصرف", "qawl": "", "nass": "هذه الآيات والتي بعدها نزلت في خلق أهل الجاهلية، وذلك لأنهم كانوا يجرون مع شهوات نفوسهم، لم يقومهم أمر من الله ولا نهي، فكان الرجل يسخر، ويهمز، ويلمز، وينبز بالألقاب، ويظن الظنون فيتكلم بها، ويغتاب، ويفتخر بنسبه، إلى غير ذلك من أخلاق النفوس البطالة، فنزلت هذه الآية تأديبا لأمة محمد صلى الله عليه وسلم. وذكر بعض الناس لهذه الآيات أسبابا … ، والقوي عندي أن هذه الآية نزلت تقويما كسائر أمر الشرع، ولو تتبعت الأسباب لكانت أكثر من أن تحصى", "qawaid": [], "tabi": ""}]}, {"id": 6097, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 16 بتصرف): «وقد يكون اللمْز بالقول وبالإشارة ونحوه مما يفهمه آخر، والهمْز لا يكون إلا باللسان. وحكى الثعلبي أنّ اللمْز ما كان في المشهد، والهمْز ما كان في المغيب. وحكى الزهراويُّ عن علي بن سليمان عكس ذلك، فقال: الهمْز أن تعيب بالحضرة، واللمْز في الغيبة».", "mawaqif": [{"taliq": 6097, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 16 بتصرف", "qawl": "", "nass": "وقد يكون اللمز بالقول وبالإشارة ونحوه مما يفهمه آخر، والهمز لا يكون إلا باللسان. وحكى الثعلبي أن اللمز ما كان في المشهد، والهمز ما كان في المغيب. وحكى الزهراوي عن علي بن سليمان عكس ذلك، فقال: الهمز أن تعيب بالحضرة، واللمز في الغيبة", "qawaid": [], "tabi": ""}]}, {"id": 6100, "kinds": "نقد،توجيه،تعليق", "text": "علَّقَ ابنُ جرير (21/ 372 - 373) على قول ابن زيد هذا، فقال: «وجَّه ابن زيد تأويل قوله: {بئس الاسم الفسوق} إلى من دعي فاسقًا وهو تائب من فِسْقِه، فبئس الاسم ذلك له من أسمائه». ثم انتَقَدَه -لدلالة السياق- بقوله: «وغير ذلك من التأويل أولى بالكلام، وذلك أنّ الله تقدّم بالنهي عما تقدّم بالنهي عنه في أول هذه الآية، فالذي هو أولى أن يختمها بالوعيد لمن تقدّم على بغْيه، أو بقبيح ركوبه ما ركب مما نُهي عنه، لا أن يخبر عن قبح ما كان التائب أتاه قبل توبته؛ إذ كانت الآية لم تفتتح بالخبر عن ركوبه ما كان ركب قبل التوبة من القبيح، فيختم آخرها بالوعيد عليه أو بالقبيح».", "mawaqif": [{"taliq": 6100, "mi": 0, "aya": 11, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "21/ 372 - 373", "qawl": "ابن زيد", "nass": "وجه ابن زيد تأويل قوله: {بئس الاسم الفسوق} إلى من دعي فاسقا وهو تائب من فسقه، فبئس الاسم ذلك له من أسمائه", "qawaid": ["السياق"], "tabi": ""}]}], "12": [{"id": 6101, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 18 - 19 بتصرف): «أمر تبارك وتعالى المؤمنين باجتناب كثير من الظن، وأن لا يعملوا ولا يتكلّموا بحسبه، لما في ذلك وفي التجسس مِن التقاطع والتدابر، وحكم على بعضه بأنّه إثم؛ إذ بعضه ليس بإثمٍ، ولا يلزم اجتنابه، وهو ظنّ الخير بالناس، وحسنه بالله تعالى، والمظنون من شهادات الشهود، والمظنون به من أهل الشرّ؛ فإنّ سقوط عدالته وغير ذلك هي من حُكم الظنّ به، وظنّ الخير بالمؤمن محمود. والظنّ المنهي عنه: هو أن يظن سوءًا برجل ظاهره الصلاح، بل الواجب أن يزيل الظنّ وحكمه ويتأوّل الخير. وقال بعض الناس: {إثم} معناه: كذب، ومنه قول النبي صلى الله عليه وسلم: «إياكم والظنّ؛ فإنّ الظنّ أكذب الحديث». وقال بعض الناس:» معنى قوله تعالى: {إن بعض الظن إثم} أي: إذا تكلم الظانّ أثِم، وما لم يتكلم فهو في فسحة؛ لأنه لا يقدر على دفع الخواطر التي يبيحها قول النبي صلى الله عليه وسلم: «الحزم سوء الظن»، وما زال أولو العزم يحترسون من سوء الظن ويسدُّون ذرائعه\".", "mawaqif": [{"taliq": 6101, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 18 - 19 بتصرف", "qawl": "", "nass": "أمر تبارك وتعالى المؤمنين باجتناب كثير من الظن، وأن لا يعملوا ولا يتكلموا بحسبه، لما في ذلك وفي التجسس من التقاطع والتدابر، وحكم على بعضه بأنه إثم؛ إذ بعضه ليس بإثم، ولا يلزم اجتنابه، وهو ظن الخير بالناس، وحسنه بالله تعالى، والمظنون من شهادات الشهود، والمظنون به من أهل الشر؛ فإن سقوط عدالته وغير ذلك هي من حكم الظن به، وظن الخير بالمؤمن محمود. والظن المنهي عنه: هو أن يظن سوءا برجل ظاهره الصلاح، بل الواجب أن يزيل الظن وحكمه ويتأول الخير. وقال بعض الناس: {إثم} معناه: كذب، ومنه قول النبي صلى الله عليه وسلم: «إياكم والظن؛ فإن الظن أكذب الحديث", "qawaid": [], "tabi": ""}]}, {"id": 6102, "kinds": "نقد", "text": "قال ابنُ عطية (8/ 19): «قال بعض الناس:» التجسُّس -بالجيم- في الشرّ، والتحسُّس -بالحاء- في الخير، وهكذا ورد القرآن، ولكن قد يتداخلان في الاستعمال. وقال أبو عمرو بن العلاء: التجسُّس: ما كان من وراء وراء. والتحسُّس -بالحاء-: الدخول والاستعلام\".\nوبنحوه قال ابنُ كثير (13/ 158).", "mawaqif": [{"taliq": 6102, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 19", "qawl": "", "nass": "قال بعض الناس:", "qawaid": [], "tabi": ""}, {"taliq": 6102, "mi": 0, "aya": 12, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 158", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}, {"id": 6103, "kinds": "نقد", "text": "قال ابنُ كثير (13/ 160): «الغِيبة محرَّمة بالإجماع، ولا يُستثنى من ذلك إلا مَن رجحت مصلحته، كما في الجرح والتعديل والنصيحة، كقوله صلى الله عليه وسلم لما استأذن عليه ذلك الرجل الفاجر: «ائذنوا له، بئس أخو العشيرة». وكقوله صلى الله عليه وسلم لفاطمة بنت قيس رضي الله عنها وقد خطبها معاوية وأبو الجهم: «أما معاوية فصعلوك، وأما أبو الجهم فلا يضع عصاه عن عاتقه». وكذا ما جرى مجرى ذلك، ثم بَقِيّتها على التحريم الشديد، وقد ورد فيها الزجر الأكيد».\nوبنحوه قال ابنُ عطية (8/ 21).", "mawaqif": [{"taliq": 6103, "mi": 0, "aya": 12, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 160", "qawl": "", "nass": "الغيبة محرمة بالإجماع، ولا يستثنى من ذلك إلا من رجحت مصلحته، كما في الجرح والتعديل والنصيحة، كقوله صلى الله عليه وسلم لما استأذن عليه ذلك الرجل الفاجر: «ائذنوا له، بئس أخو العشيرة", "qawaid": [], "tabi": ""}, {"taliq": 6103, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 21", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن كثير"}]}, {"id": 6104, "kinds": "غيره", "text": "قال ابنُ تيمية (6/ 62 - 63): «المغتاب له سبيل إلى التوبة بكل حال، وإن كان الذي اغتيب ميتًا أو غائبًا، بل على أصح الروايتين ليس عليه أن يستحلّه في الدنيا إذا لم يكن عَلِمَ؛ فإن فساد ذلك أكثر من صلاحه، وفي الأثر: «كفارة الغِيبة أن تستغفر لمن اغتبته»، وقد قال تعالى: {إنَّ الحَسَناتِ يُذْهِبْنَ السَّيِّئاتِ}».", "mawaqif": [{"taliq": 6104, "mi": 0, "aya": 12, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 62 - 63", "qawl": "", "nass": "المغتاب له سبيل إلى التوبة بكل حال، وإن كان الذي اغتيب ميتا أو غائبا، بل على أصح الروايتين ليس عليه أن يستحله في الدنيا إذا لم يكن علم؛ فإن فساد ذلك أكثر من صلاحه، وفي الأثر: «كفارة الغيبة أن تستغفر لمن اغتبته", "qawaid": [], "tabi": ""}]}], "13": [{"id": 6105, "kinds": "بيان،نقل", "text": "قال ابن عطية (8/ 23): «قوله تعالى: {من ذكر وأنثى} يحتمل أن يريد: آدم وحواء. فكأنه قال: إنا خلقنا جميعكم من آدم وحواء. ويحتمل أن يريد: الذكر والأنثى اسم الجنس. فكأنه قال: إنّا خلَقنا كل واحد منكم من ماء ذكر وماء أنثى. وقصد هذه الآية التسوية بين الناس».", "mawaqif": [{"taliq": 6105, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 23", "qawl": "", "nass": "قوله تعالى: {من ذكر وأنثى} يحتمل أن يريد: آدم وحواء. فكأنه قال: إنا خلقنا جميعكم من آدم وحواء. ويحتمل أن يريد: الذكر والأنثى اسم الجنس. فكأنه قال: إنا خلقنا كل واحد منكم من ماء ذكر وماء أنثى. وقصد هذه الآية التسوية بين الناس", "qawaid": [], "tabi": ""}]}, {"id": 6106, "kinds": "توجيه،نقل", "text": "قال ابنُ عطية (8/ 24): «والشُّعوب: جمع شعب، وهو أعظم ما يوجد من جماعات الناس مرتبطًا بنسب واحد، ويتلوه القبيلة، ثم العمارة، ثم البطن، ثم الفخذ، ثم الأسرة والفصيلة: وهما قرابة الرجل الأدنون، فمُضر وربيعة وحِمْير شعوب، وقيس وتميم ومذحج ومراد قبائل مشبهة بقبائل الرأس؛ لأنها قطع تقابلت، وقريش ومحارب وسليم عمارات، وبنو قصي وبنو مخزوم بطون، وبنو هاشم وبنو أمية أفخاذ، وبنو عبد المطلب أسرة وفصيلة، وقال ابن جُبير: الشعوب: الأفخاذ. ورُوي عن ابن عباس: الشّعوب: البطون، وهذا غير ما تمالأ عليه اللغويون. قال الثعلبي: وقيل: الشُّعوب في العجم، والقبائل في العرب، والأسباط في بني إسرائيل. وأما الشّعب الذي هو في همدان الذي يُنسب إليه الشعبي فهو بطن يقال له الشعب. وقيل للأمم التي ليست بعرب شعوبية نسبة إلى الشُّعوب، وذلك أنّ تفصيل أنسابها خفيٌّ، فلم يعرف أحد منهم إلا بأن يقال: فارسي تركي رومي، فكأنهم عرفوا بشعوبهم، وهي أعمّ ما يعبر به عن جماعتهم، ويقال لهم: الشَّعوبية -بفتح الشين-، وهذا من تعيين النّسب، وقد قيل فيهم غير ما ذكرت، وهذا أولى عندي».", "mawaqif": [{"taliq": 6106, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 24", "qawl": "", "nass": "والشعوب: جمع شعب، وهو أعظم ما يوجد من جماعات الناس مرتبطا بنسب واحد، ويتلوه القبيلة، ثم العمارة، ثم البطن، ثم الفخذ، ثم الأسرة والفصيلة: وهما قرابة الرجل الأدنون، فمضر وربيعة وحمير شعوب، وقيس وتميم ومذحج ومراد قبائل مشبهة بقبائل الرأس؛ لأنها قطع تقابلت، وقريش ومحارب وسليم عمارات، وبنو قصي وبنو مخزوم بطون، وبنو هاشم وبنو أمية أفخاذ، وبنو عبد المطلب أسرة وفصيلة، وقال ابن جبير: الشعوب: الأفخاذ. وروي عن ابن عباس: الشعوب: البطون، وهذا غير ما تمالأ عليه اللغويون. قال الثعلبي: وقيل: الشعوب في العجم، والقبائل في العرب، والأسباط في بني إسرائيل. وأما الشعب الذي هو في همدان الذي ينسب إليه الشعبي فهو بطن يقال له الشعب. وقيل للأمم التي ليست بعرب شعوبية نسبة إلى الشعوب، وذلك أن تفصيل أنسابها خفي، فلم يعرف أحد منهم إلا بأن يقال: فارسي تركي رومي، فكأنهم عرفوا بشعوبهم، وهي أعم ما يعبر به عن جماعتهم، ويقال لهم: الشعوبية -بفتح الشين-، وهذا من تعيين النسب، وقد قيل فيهم غير ما ذكرت، وهذا أولى عندي", "qawaid": [], "tabi": ""}]}, {"id": 6107, "kinds": "استدلال", "text": "قال ابن كثير (13/ 173): «قد استدل بهذه الآية الكريمة، وهذه الأحاديث الشريفة مَن ذهب من العلماء إلى أن الكفاءة في النكاح لا تُشترط، ولا يُشترط سوى الدين؛ لقوله تعالى: {إن أكرمكم عند الله أتقاكم}».", "mawaqif": [{"taliq": 6107, "mi": 0, "aya": 13, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 173", "qawl": "", "nass": "قد استدل بهذه الآية الكريمة، وهذه الأحاديث الشريفة من ذهب من العلماء إلى أن الكفاءة في النكاح لا تشترط، ولا يشترط سوى الدين؛ لقوله تعالى: {إن أكرمكم عند الله أتقاكم}", "qawaid": [], "tabi": ""}]}, {"id": 6109, "kinds": "بيان،نقل", "text": "قال ابنُ تيمية (6/ 64 - 65) تعليقًا على هذا الحديث: \"بيّن لهم أولًا: أنّ أكرم الخلق عند الله أتقاهم، وإن لم يكن ابن نبي ولا أبا نبي، فإبراهيم النبي صلى الله عليه وسلم أكرم على الله من يوسف، وإن كان أبوه آزر، وهذا أبوه يعقوب. وكذلك نوح أكرم على الله من إسرائيل، وإن كان هذا أولاده أنبياء، وهذا أولاده ليسوا بأنبياء. فلمّا ذكروا أنه ليس مقصودهم إلا الأنساب، قال لهم: فأكرم أهل الأنساب مَن انتسب إلى الأنبياء، وليس في ولد آدم مثل يوسف؛ فإنه نبي ابن نبي ابن نبي. فلما أشاروا إلى أنه ليس مقصودهم إلا ما يتعلق بهم، قال: «أفعن معادن العرب تسألوني؟». الناس معادن كمعادن الذهب والفِضّة، «خيارهم في الجاهلية خيارهم في الإسلام إذا فقهوا» بيّن أن الأنساب كالمعادن، فإن الرجل يتولد منه كما يتولّد من المعدن الذهب والفِضّة. ولا ريب أن الأرض التي تُنبتُ الذّهب أفضل من الأرض التي تُنبت الفِضّة. فهكذا مَن عُرِف أنه يلد الأفاضل، كان أولاده أفضل مِمَّن عُرف أنه يلد المفضول. لكن هذا سبب ومظنة، وليس هو لازمًا؛ فربما تعطلت أرض الذّهب، وربما قلَّ نَبْتها، فحينئذ تكون أرض الفِضّة أحبَّ إلى الإنسان من أرضٍ مُعطّلة، والفِضّة الكثيرة أحب إليهم من ذهبٍ قليل لا يماثلها في القدر، فلهذا كانت أهل الأنساب الفاضلة يُظن بهم الخير، ويُكرمون لأجل ذلك، فإذا تحقّق من أحدهم خلاف ذلك، كانت الحقيقة مُقدّمة على المظنّة، وأما [ما] عند الله فلا يثبت على المظان ولا على الدلائل، إنما يثبت على ما يعمله هو من الأعمال الصالحة، فلا يحتاج إلى دليل، ولا يجتزئ بالمظنّة، فلهذا كان أكرم الخلق عنده أتقاهم. فإذا قُدِّر تماثل اثنين عنده في التقوى تماثلًا في الدرجة، وإن كان أبو أحدهما أو ابنه أفضل من أبي الآخر أو ابنه، لكن إن حصل له بسبب نسبه زيادة في التقوى كان أفضل لزيادة تقواه. ولهذا حصل لأزواج النبي صلى الله عليه وسلم إذا قنتن لله ورسوله وعملن صالحًا، لا لمجرد المصاهرة، بل لكمال الطاعة، كما أنهن لو أتين بفاحشة مبيّنة لضوعف لهُنّ العذاب ضعفين؛ لقبح المعصية. فإنّ ذا الشرف إذا ألزم نفسه التقوى كان تقواه أكمل من تقوى غيره، كما أنّ الملِك إذا عدل كان عدله أعظم من عدل الرجل في أهله. ثم إنّ الرجل إذا قصد الخير قصدًا جازمًا، وعمل منه ما يقدر عليه، كان له أجر كامل، كما قال النبي صلى الله عليه وسلم في الحديث الصحيح: «إن بالمدينة رجالًا ما سرتم مسيرًا ولا قطعتم واديًا إلا كانوا معكم». قالوا: وهم في المدينة؟ قال: «وهم بالمدينة، حبَسهم العُذر». ولهذا قال النبي صلى الله عليه وسلم في الصحيح: «مَن دعا إلى هُدًى كان له من الأجر مثل أجور مَن اتّبعه، من غير أن ينقص من أجورهم شيئًا، ومَن دعا إلى ضلالة كان عليه من الوزر مثل أوزار مَن اتّبعه، من غير أن ينقص من أوزارهم شيئًا».", "mawaqif": [{"taliq": 6109, "mi": 0, "aya": 13, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 64 - 65", "qawl": "", "nass": "أفعن معادن العرب تسألوني؟", "qawaid": [], "tabi": ""}]}], "14": [{"id": 6110, "kinds": "تعليق،نقل", "text": "عَلَّقَ ابنُ تيمية (6/ 77) على هذا القول بقوله: «وأما ما نقل من أنهم أسلموا خوْف القتْل والسبي فهكذا كان إسلام غير المهاجرين والأنصار، أسلموا رغبة ورهبة، كإسلام الطُّلقاء من قريش بعد أن قهرهم النبي صلى الله عليه وسلم، وإسلام المُؤلّفة قلوبهم من هؤلاء ومن أهل نَجد، وليس كل من أسلم لرغبة أو رهبة كان من المنافقين الذين هم في الدَّرْك الأسفل من النار، بل يدخلون في الإسلام والطاعة وليس في قلوبهم تكذيب ومعاداة للرسول، ولا استنارت قلوبهم بنور الإيمان ولا استبصروا فيه، وهؤلاء قد يحسن إسلام أحدهم فيصير من المؤمنين كأكثر الطُّلَقاء، وقد يبقى من فُسّاق الملة، ومنهم مَن يصير منافقًا مُرتابًا إذا قال له منكر ونكير: ما تقول في هذا الرجل الذي بعُث فيكم؟ فيقول: هاه هاه لا أدري، سمعت الناس يقولون شيئًا فقلتُه. وقد تقدم قول مَن قال: إنهم أسلموا بغير قتال. فهؤلاء كانوا أحسن إسلامًا من غيرهم، وإنّ الله إنما ذمّهم لكوْنهم مَنُّوا بالإسلام وأنزل فيهم: {ولا تبطلوا أعمالكم} [محمد: 23]، وأنهم من جنس أهل الكبائر. وأيضًا قوله: {ولكن قولوا أسلمنا ولما يدخل الإيمان في قلوبكم}، و» لما «إنما يُنفى بها ما يُنتَظَر ويكون حصوله مترقّبًا؛ كقوله: {أم حسبتم أن تدخلوا الجنة ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين} [آل عمران: 142]، وقوله: {أم حسبتم أن تدخلوا الجنة ولما يأتكم مثل الذين خلوا من قبلكم} [البقرة: 215]، فقوله: {ولما يدخل الإيمان في قلوبكم} يدل على أنّ دخول الإيمان منتظرٌ منهم؛ فإنّ الذي يدخل في الإسلام ابتداء لا يكون قد حصل في قلبه الإيمان، لكنه يحصل فيما بعد كما في الحديث: كان الرجل يُسلم أول النهار رغبة في الدنيا فلا يجيء آخر النهار إلا والإسلام أحبّ إليه مما طلعت عليه الشمس. ولهذا كان عامة الذين أسلموا رغبة ورهبة دخل الإيمان في قلوبهم بعد ذلك، وقوله: {ولكن قولوا أسلمنا} أمرٌ لهم بأن يقولوا ذلك والمنافق لا يؤمر بشيء، ثم قال: {وإن تطيعوا الله ورسوله لا يلتكم من أعمالكم شيئا} والمنافق لا تنفعه طاعة الله ورسوله حتى يؤمن أولًا».", "mawaqif": [{"taliq": 6110, "mi": 0, "aya": 14, "alam": "ابن تيمية", "fil": "علق", "kind": "تعليق", "ref": "6/ 77", "qawl": "بقوله", "nass": "وأما ما نقل من أنهم أسلموا خوف القتل والسبي فهكذا كان إسلام غير المهاجرين والأنصار، أسلموا رغبة ورهبة، كإسلام الطلقاء من قريش بعد أن قهرهم النبي صلى الله عليه وسلم، وإسلام المؤلفة قلوبهم من هؤلاء ومن أهل نجد، وليس كل من أسلم لرغبة أو رهبة كان من المنافقين الذين هم في الدرك الأسفل من النار، بل يدخلون في الإسلام والطاعة وليس في قلوبهم تكذيب ومعاداة للرسول، ولا استنارت قلوبهم بنور الإيمان ولا استبصروا فيه، وهؤلاء قد يحسن إسلام أحدهم فيصير من المؤمنين كأكثر الطلقاء، وقد يبقى من فساق الملة، ومنهم من يصير منافقا مرتابا إذا قال له منكر ونكير: ما تقول في هذا الرجل الذي بعث فيكم؟ فيقول: هاه هاه لا أدري، سمعت الناس يقولون شيئا فقلته. وقد تقدم قول من قال: إنهم أسلموا بغير قتال. فهؤلاء كانوا أحسن إسلاما من غيرهم، وإن الله إنما ذمهم لكونهم منوا بالإسلام وأنزل فيهم: {ولا تبطلوا أعمالكم} [محمد: 23]، وأنهم من جنس أهل الكبائر. وأيضا قوله: {ولكن قولوا أسلمنا ولما يدخل الإيمان في قلوبكم}، و", "qawaid": [], "tabi": ""}]}, {"id": 6111, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 25 - 26 بتصرف): «هم أعراب مخصوصون، وقد أخبر الله تعالى أنّ في الأعراب على الجملة مَن يؤمن بالله واليوم الآخر، فأمر الله تعالى نبيّه صلى الله عليه وسلم أن يقول لهؤلاء المُدَّعين في الإيمان: {لم تؤمنوا} أي: لم تصدِّقوا بقلوبكم، {ولكن قولوا أسلمنا}. والإسلام يقال بمعنيين: أحدهما: الدّين يعم الإيمان والأعمال، وهو الذي في قوله: {إن الدين عند الله الإسلام} [آل عمران: 19]، والذي في قوله صلى الله عليه وسلم: «بُني الإسلام على خمس». والذي في تعليم النبي صلى الله عليه وسلم لجبريل حين قال له: ما الإسلام؟ قال: «أن تعبد الله وحده ولا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزّكاة، وتصوم رمضان». والذي في قوله لسعد بن أبي وقاص: «أو مسلمًا، إني لأعطي الرجل وغيره أحب إلي منه» الحديث. فهذا الإسلام ليس هو في قوله: {ولكن قولوا أسلمنا}. والمعنى الثاني للفظ الإسلام: هو الاستسلام والإظهار الذي يستعصم به ويحقن الدم، وهذا هو الإسلام في قوله: {ولكن قولوا أسلمنا}، والإيمان الذي هو التصديق أخص من الأول».\nوقال ابنُ كثير (13/ 174): «قد استُفِيد من هذه الآية الكريمة أنّ الإيمان أخص من الإسلام كما هو مذهب أهل السنة والجماعة، ويدل عليه حديث جبريل عليه السلام حين سأل عن الإسلام، ثم عن الإيمان، ثم عن الإحسان، فترقّى من الأعم إلى الأخص، ثم للأخص منه».", "mawaqif": [{"taliq": 6111, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 25 - 26 بتصرف", "qawl": "", "nass": "هم أعراب مخصوصون، وقد أخبر الله تعالى أن في الأعراب على الجملة من يؤمن بالله واليوم الآخر، فأمر الله تعالى نبيه صلى الله عليه وسلم أن يقول لهؤلاء المدعين في الإيمان: {لم تؤمنوا} أي: لم تصدقوا بقلوبكم، {ولكن قولوا أسلمنا}. والإسلام يقال بمعنيين: أحدهما: الدين يعم الإيمان والأعمال، وهو الذي في قوله: {إن الدين عند الله الإسلام} [آل عمران: 19]، والذي في قوله صلى الله عليه وسلم: «بني الإسلام على خمس", "qawaid": [], "tabi": ""}, {"taliq": 6111, "mi": 0, "aya": 14, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 174", "qawl": "", "nass": "قد استفيد من هذه الآية الكريمة أن الإيمان أخص من الإسلام كما هو مذهب أهل السنة والجماعة، ويدل عليه حديث جبريل عليه السلام حين سأل عن الإسلام، ثم عن الإيمان، ثم عن الإحسان، فترقى من الأعم إلى الأخص، ثم للأخص منه", "qawaid": [], "tabi": ""}]}, {"id": 6114, "kinds": "غيره", "text": "قال ابنُ جرير (21/ 394) مبيّنًا معنى الآية استنادًا إلى أثر قتادة: «يقول -تعالى ذكره-: إن الله ذو عفوٍ -أيها الأعراب- لِمَن أطاعه، وتاب إليه مِن سالف ذنوبه، فأطيعوه، وانتهوا إلى أمره ونهيه، يغفر لكم ذنوبكم، {رحيم} بخلْقه التائبين إليه أن يعاقبهم بعد توبتهم من ذنوبهم على ما تابوا منه، فتوبوا إليه يرحمكم».", "mawaqif": [{"taliq": 6114, "mi": 0, "aya": 14, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "21/ 394", "qawl": "", "nass": "يقول -تعالى ذكره-: إن الله ذو عفو -أيها الأعراب- لمن أطاعه، وتاب إليه من سالف ذنوبه، فأطيعوه، وانتهوا إلى أمره ونهيه، يغفر لكم ذنوبكم، {رحيم} بخلقه التائبين إليه أن يعاقبهم بعد توبتهم من ذنوبهم على ما تابوا منه، فتوبوا إليه يرحمكم", "qawaid": ["أقوال السلف"], "tabi": ""}]}], "15": [{"id": 6115, "kinds": "نقل", "text": "قال ابنُ تيمية (6/ 69) تعليقًا على الآية: «دلَّ البيانُ على أنّ الإيمان المنفيَّ عن هؤلاء الأعراب: هو هذا الإيمان الذي نُفي عن فُسّاق أهل القبلة الذين لا يُخلَّدون في النار، بل قد يكون مع أحدهم مثقال ذرّة من إيمان، ونفيُ هذا الإيمان لا يقتضي ثبوت الكفر الذي يخلَّد صاحبه في النار».", "mawaqif": [{"taliq": 6115, "mi": 0, "aya": 15, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 69", "qawl": "", "nass": "دل البيان على أن الإيمان المنفي عن هؤلاء الأعراب: هو هذا الإيمان الذي نفي عن فساق أهل القبلة الذين لا يخلدون في النار، بل قد يكون مع أحدهم مثقال ذرة من إيمان، ونفي هذا الإيمان لا يقتضي ثبوت الكفر الذي يخلد صاحبه في النار", "qawaid": [], "tabi": ""}]}], "17": [{"id": 6116, "kinds": "تعليق", "text": "قال ابنُ عطية (8/ 27): «وقوله تعالى: {أنْ} يحتمل أن يكون مفعولًا صريحًا. ويحتمل أن يكون مفعولًا من أجله. وقوله: {بل الله يمن عليكم أن هداكم للإيمان} أي: بزعمكم إذ تقولون آمنّا، فقد لزمكم أن الله مانٌّ عليكم، ويدلّك على هذا المعنى قوله: {إن كنتم صادقين} فعلَّق عليهم الحكمين: هم ممنون عليهم على الصدق، وأهلٌ أن يقولوا أسلمنا من حيث هم كذبة».\nوبنحوه قال ابنُ جرير (21/ 398 - 399).", "mawaqif": [{"taliq": 6116, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 27", "qawl": "", "nass": "وقوله تعالى: {أن} يحتمل أن يكون مفعولا صريحا. ويحتمل أن يكون مفعولا من أجله. وقوله: {بل الله يمن عليكم أن هداكم للإيمان} أي: بزعمكم إذ تقولون آمنا، فقد لزمكم أن الله مان عليكم، ويدلك على هذا المعنى قوله: {إن كنتم صادقين} فعلق عليهم الحكمين: هم ممنون عليهم على الصدق، وأهل أن يقولوا أسلمنا من حيث هم كذبة", "qawaid": [], "tabi": ""}, {"taliq": 6116, "mi": 0, "aya": 17, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "21/ 398 - 399", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}, {"id": 6117, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 27): «وقوله تعالى: {يمن عليكم} يحتمل أن يكون بمعنى: ينعم، كما تقول: منّ الله عليك. ويحتمل أن يكون بمعنى: يذكر إحسانه، فيجيء معادلًا لـ {يمنون عليك}، وقال الناس قديمًا: إذا كفرت النعمة حسُنت المنّة. وإنما المنّة المُبطلة للصدقة المكروهة ما وقع دون كُفر النعمة».", "mawaqif": [{"taliq": 6117, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 27", "qawl": "", "nass": "وقوله تعالى: {يمن عليكم} يحتمل أن يكون بمعنى: ينعم، كما تقول: من الله عليك. ويحتمل أن يكون بمعنى: يذكر إحسانه، فيجيء معادلا ل {يمنون عليك}، وقال الناس قديما: إذا كفرت النعمة حسنت المنة. وإنما المنة المبطلة للصدقة المكروهة ما وقع دون كفر النعمة", "qawaid": [], "tabi": ""}]}]}, "athar": {"71808": {"num": 71808, "aya": 13, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير -من طريق أبي حُصين- في قوله عز وجل: {وجعلناكم شعوبا وقبائل لتعارفوا}، قال: الشعوب: نحو تميم وبكر، والقبائل: الأفخاذ."}, "71809": {"num": 71809, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {وجَعَلْناكُمْ شُعُوبًا} قال: النّسب البعيد، {وقَبائِلَ} قال: دون ذلك؛ {لِتَعارَفُوا} جعَلْنا هذا لتعرفوا فلان بن فلان من كذا وكذا."}, "71813": {"num": 71813, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {وجَعَلْناكُمْ شُعُوبًا وقَبائِلَ}، قال: الشّعب: هو النّسب البعيد، والقبائل: كما سمعتَه يقول: فلان من بني فلان."}, "71847": {"num": 71847, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال قتادة بن دعامة، في قوله: {ولَكِنْ قُولُوا أسْلَمْنا}: ولكن قولوا: السيف."}, "71819": {"num": 71819, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطاء- قال: لا أرى أحدًا يعمل بهذه الآية: {يا أيُّها النّاسُ إنّا خَلَقْناكُمْ مِن ذَكَرٍ وأُنْثى} حتى بلغ: {إنَّ أكْرَمَكُمْ عِنْدَ اللَّهِ أتْقاكُمْ}، فيقول الرجلُ للرجل: أنا أكرم منك. فليس أحدٌ أكرمَ مِن أحد إلا بتقوى الله."}, "71821": {"num": 71821, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة، في هذه الآية: أكرم الكرم التقوى، وألأم اللؤم الفجور."}, "71824": {"num": 71824, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: قال رسول الله صلى الله عليه وسلم: «إنّ الله تعالى قسم الخلْق قسمين، فجعلني في خيرهما قسمًا، فذلك قوله: {وأصحاب اليمين} [الواقعة: 27]، {وأصحاب الشمال} [الواقعة: 41]، فأنا مِن أصحاب اليمين، وأنا مِن خير أصحاب اليمين، ثم جعل القسمين بيوتًا، فجعلني في خيرهما بيتًا، فذلك قوله: {فأصحاب الميمنة ما أصحاب الميمنة وأصحاب المشأمة ما أصحاب المشأمة والسابقون السابقون} [الواقعة: 8 - 10]، فأنا من خير السابقين، ثم جعل البيوت قبائل، فجعلني في خيرها قبيلة، فذلك قوله: {شعوبا وقبائل}، فأنا أتقى ولد آدم وأكرمهم على الله عز وجل ولا فخر، ثم جعل القبائل بيوتًا، فجعلني في خيرها بيتًا، فذلك قوله: {إنما يريد الله ليذهب عنكم الرجس أهل البيت ويطهركم تطهيرا} [الأحزاب: 33]»."}, "71697": {"num": 71697, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة-: أنّ صفيّة بنت حُييّ بن أخطب أتتْ رسول الله صلى الله عليه وسلم، فقالت: إنّ النساء يُعَيِّرْنَنْيِ فيَقُلن: يا يهودية بنت يهوديّين. فقال رسول الله صلى الله عليه وسلم: «هلّا قلتِ: إنّ أبي هارون، وابن عمّي موسى، وإنّ زوجي محمّد». فأنزل الله هذه الآية."}, "71699": {"num": 71699, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، {يا أيُّها الَّذِينَ آمَنُوا لا يَسْخَرْ قَوْمٌ مِن قَوْمٍ} الآية، قال: نَزَلتْ في ثابت بن قيس، وذلك أنّه كان في أُذنه وقْر، فكان إذا أتى رسول الله صلى الله عليه وسلم، وقد سبقوه بالمجلس، أوسعوا له حتّى يجلس إلى جَنبه، فيسمع ما يقول، فأقبل ذات يوم وقد فاته من صلاة الفجر ركعة مع رسول الله صلى الله عليه وسلم، فلمّا انصرف النبيّ صلى الله عليه وسلم من الصلاة أخذ أصحابُه مجالسهم منه، فربض كلّ رجل بمجلسه، فلا يكاد يوسع أحدٌ لأحد، فكان الرجل إذا جاء فلم يجد مجلسًا قام قائمًا كما هو، فلمّا فرغ ثابت من الصلاة وقام منها أقبل نحو رسول الله صلى الله عليه وسلم، فجعل يتخطّى رقاب الناس، ويقول: تفسّحوا تفسّحوا. فجعلوا يتفسّحون له حتّى انتهى إلى رسول الله صلى الله عليه وسلم وبينه وبينه رجل. فقال له: تفسّح. فقال له الرجل: قد أصبتَ مجلسًا، فاجلس. فجلس ثابت مِن خلفه مُغضبًا، فلمّا أبينت الظُّلْمة غمز ثابت الرجل، وقال: مَن هذا؟ قال: أنا فلان. فقال له ثابت: ابن فلانة! ذكر أمًّا له كان يُعيّر بها في الجاهلية، فنكّس الرجل رأسه واستحيا؛ فأنزل الله عز وجل هذه الآية."}, "71703": {"num": 71703, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {لا يَسْخَرْ قَوْمٌ مِن قَوْمٍ}، قال: لا يستهزئ قومٌ بقوم؛ إن يكن رجلًا غنيًّا أو فقيرًا أو تفضّل رجل عليه، فلا يستهزئ به."}, "71705": {"num": 71705, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {يا أيُّها الَّذِينَ آمَنُوا لا يَسْخَرْ قَوْمٌ مِن قَوْمٍ عَسى أنْ يَكُونُوا خَيْرًا مِنهُمْ ولا نِساءٌ مِن نِساءٍ عَسى أنْ يَكُنَّ خَيْرًا مِنهُنَّ} قال: ربما عُثر على المرء عند خطيئته {عَسى أنْ يَكُونُوا خَيْرًا مِنهُمْ} فإن كان ظُهر على عَثْرته هذه، وسُترْتَ أنت على عَثْرتك، لعلّ هذه التي ظَهرتْ خيرٌ له في الآخرة عند الله، وهذه التي سُترتَ أنت عليها شرٌّ لك، ما يدريك لعلّه لا تُغفر لك. قال: فنهى الله الرجال عن ذلك، فقال: {لا يَسْخَرْ قَوْمٌ مِن قَوْمٍ عَسى أنْ يَكُونُوا خَيْرًا مِنهُمْ} وقال في النساء مثل ذلك."}, "71833": {"num": 71833, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "قال عبد الله بن عباس: كرَم الدنيا: الغِنى، وكرَم الآخرة: التقوى."}, "71707": {"num": 71707, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {ولا تَلْمِزُوا أنْفُسَكُمْ}، قال: لا يَطْعن بعضكم على بعض."}, "71708": {"num": 71708, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولا تَلْمِزُوا أنْفُسَكُمْ}، قال: لا يَطْعُنْ بعضكم على بعض."}, "71834": {"num": 71834, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق يزيد- قال: ما تعُدّون الكَرم؟ وقد بيّن الله الكَرم، وأكرمكم عند الله أتقاكم، وما تعُدّون الحَسب؟ أفضلُكم حسبًا أحسنكم خُلقًا."}, "71710": {"num": 71710, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- {ولا تَلْمِزُوا أنْفُسَكُمْ}، قال: لا يَطْعُن بعضكم على بعض."}, "71836": {"num": 71836, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قوله: {قالَتِ الأَعْرابُ آمَنّا}، قال: أعراب بني أسَد بن خزيمة."}, "71837": {"num": 71837, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة، في قوله: {قالَتِ الأَعْرابُ آمَنّا}، قال: نَزَلتْ في بني أسَد."}, "71713": {"num": 71713, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس: {ولا تَنابَزُوا بِالأَلْقابِ} أنها نَزَلتْ في صفيّة بنت حُييّ بن أخطب، قال لها النساء: يهودية بنت يهوديّين."}, "71714": {"num": 71714, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، في قوله: {ولا تَنابَزُوا بِالأَلْقابِ} قال: كان هذا الحي من الأنصار قلَّ رجل منهم إلا وله اسمان أو ثلاثة، فربّما دعا النبيُّ صلى الله عليه وسلم الرجلَ منهم ببعض تلك الأسماء، فيقال: يا رسول الله، إنّه يكره هذا الاسم. فأنزل الله: {ولا تَنابَزُوا بِالأَلْقابِ}."}, "71715": {"num": 71715, "aya": 11, "qail": "أبي جبيرة بن الضحاك", "tabaqa": "", "bab": "نزول الآية", "text": "عن أبي جَبيرة بن الضَّحّاك، قال: فينا نَزَلتْ؛ في بني سَلِمة: {ولا تَنابَزُوا بِالأَلْقابِ}؛ قدم رسول الله صلى الله عليه وسلم المدينةَ وليس فينا رجلٌ إلا وله اسمان أو ثلاثة، فكان إذا دعا أحدَهم باسمٍ مِن تلك الأسماء قالوا: يا رسول الله، إنّه يكرهه. فنَزَلتْ: {ولا تَنابَزُوا بِالأَلْقابِ}."}, "71841": {"num": 71841, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية- {قالَتِ الأَعْرابُ آمَنّا قُلْ لَمْ تُؤْمِنُوا ولَكِنْ قُولُوا أسْلَمْنا} الآية، قال: وذلك أنهم أرادوا أن يتسمَّوا باسم الهجرة، وألّا يتسمَّوا بأسمائهم التي سمّاهم الله، وكان هذا أول الهجرة قبل أن تنزل المواريث لهم."}, "71838": {"num": 71838, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- {قالَتِ الأَعْرابُ آمَنّا} قال: لَعمْري، ما عمّت هذه الآية الأعراب، إنّ من الأعراب لَمَن يؤمن بالله واليوم الآخر، ولكن إنما أُنَزِلتْ في حيٍّ مِن أحياء العرب مَنُّوا بالإسلام على النبيِّ صلى الله عليه وسلم، وقالوا: أسْلمنا ولم نقاتلك كما قاتلك بنو فلان. فقال الله: {قُلْ لَمْ تُؤْمِنُوا ولَكِنْ قُولُوا أسْلَمْنا ولَمّا يَدْخُلِ الإيمانُ فِي قُلُوبِكُمْ}."}, "71842": {"num": 71842, "aya": 14, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جُبير -من طريق رباح بن أبي معروف- {ولَكِنْ قُولُوا أسْلَمْنا}، قال: استَسْلمنا لخوف السّباء والقتْل."}, "71719": {"num": 71719, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- {ولا تَنابَزُوا بِالأَلْقاب}، قال: التنابز بالألقاب: أن يكون الرجل عَمِل السيئات ثم تاب منها وراجع الحقّ، فنهى الله أن يُعيّر بما سلف من عمله."}, "71844": {"num": 71844, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولَكِنْ قُولُوا أسْلَمْنا}، قال: استَسْلمنا مخافة القتْل والسبيِ."}, "71721": {"num": 71721, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولا تَنابَزُوا بِالأَلْقابِ}، قال: يُدعى الرجل بالكفر وهو مسلم."}, "71846": {"num": 71846, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- {قالَتِ الأَعْرابُ آمَنّا} الآية، قال: لم تَعمّ هذه الآية الأعراب، ولكنها لطوائف من الأعراب."}, "71851": {"num": 71851, "aya": 14, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {قالَتِ الأَعْرابُ آمَنّا} قال: لم يُصدِّقوا إيمانهم بأعمالهم، فردّ الله ذلك عليهم: {قُلْ لَمْ تُؤْمِنُوا ولَكِنْ قُولُوا أسْلَمْنا} وأخبرهم أنّ المؤمنين الذين آمنوا بالله ورسوله، ثم لم يرتابوا، وجاهدوا بأموالهم وأنفسهم في سبيل الله، أولئك هم الصادقون، صدّقوا إيمانهم بأعمالهم؛ فمَن قال منهم: أنا مؤمن. فقد صدق. قال: وأمّا مَن انتحل الإيمان بالكلام ولم يعمل فقد كذب، وليس بصادق."}, "71852": {"num": 71852, "aya": 14, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- وقرأ قول الله: {ولَكِنْ قُولُوا أسْلَمْنا}: استَسْلمنا، دخلنا في السّلم، وتركنا المحاربة والقتال بقولهم: لا إله إلا الله. وقال: قال رسول الله صلى الله عليه وسلم: «أُمرتُ أن أقاتل الناس حتى يقولوا: لا إله إلا الله، فإذا قالوا: لا إله إلا الله، عصموا مني دماءهم وأموالهم إلا بحقّها، وحسابهم على الله»."}, "71853": {"num": 71853, "aya": 14, "qail": "سعد بن أبي وقاص", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن سعد بن أبي وقاص: أنّ نَفرًا أتَوا رسول الله صلى الله عليه وسلم، فأعطاهم إلا رجلًا منهم، فقلتُ: يا رسول الله: أعطيتَهم وتركتَ فلانًا! واللهِ، إنِّي لَأراه مؤمنًا. فقال رسول الله صلى الله عليه وسلم: «أو مسلمًا» قال ذلك ثلاثًا."}, "71726": {"num": 71726, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {ولا تَنابَزُوا بِالأَلْقابِ}، قال: لا تقُل لأخيك المسلم: يا فاسق، يا منافق."}, "71854": {"num": 71854, "aya": 14, "qail": "سعد", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن سعد: أنّ رسول الله صلى الله عليه وسلم قسَم قَسْمًا، فأعطى أُناسًا ومنع آخرين، فقلت: يا رسول الله، أعطيتَ فلانًا وفلانًا، ومنعتَ فلانًا وهو مؤمن! فقال: «لا تقُل: مؤمن. ولكن قُل: مسلم»."}, "71728": {"num": 71728, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولا تَنابَزُوا بِالأَلْقابِ}، قال: تسميته بالأعمال السيئة بعد الإسلام: زانٍ، فاسق. (ز) {بِئْسَ الِاسْمُ الْفُسُوقُ بَعْدَ الْإِيمَانِ}"}, "71858": {"num": 71858, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن مجاهد بن جبر -من طريق ابن جُرَيْج- «لايَألِتْكُمْ»: لا ينقصكم."}, "71732": {"num": 71732, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- وقرأ: {بِئْسَ الِاسْمُ الفُسُوقُ}، قال: بئس الاسم الفسوق حين تُسمّيه بالفسق بعد الإسلام، وهو على الإسلام. قال: وأهل هذا الرأي هم المعتزلة، قالوا: لا نكفّره كما كفّره أهل الأهواء، ولا نقول له: مؤمن كما قالت الجماعة، ولكنّا نُسمّيه باسمه إن كان سارقًا فهو سارق، وإن كان خائنًا سمَّوه خائنًا، وإن كان زانيًا سمَّوه زانيًا. قال: فاعتزلوا الفريقين؛ أهل الأهواء وأهل الجماعة، فلا بقوْل هؤلاء قالوا، ولا بقوْل هؤلاء، فسُمّوا بذلك المعتزلة."}, "71734": {"num": 71734, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ومَن لَمْ يَتُبْ فَأُولَئِكَ هُمُ الظّالِمُونَ}، قال: ومَن لم يتب من ذلك الفسوق فأولئك هم الظالمون."}, "71862": {"num": 71862, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس: أن نافع بن الأزرق سأله عن قوله: {لا يَلِتْكُمْ}. قال: لا يَنقُصُكم، بلغة بني عبس. قال: وهل تعرف العرب ذلك؟ قال: نعم، أما سمعت قول الحطيئة العَبسيّ: أبْلِغ سَراة بني سعدٍ مُغَلْغلةً … جَهْد الرِّسالة لا ألْتًا ولا كذِبًا!."}, "71863": {"num": 71863, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {لا يَلِتْكُمْ}، قال: لا يظلمكم."}, "71864": {"num": 71864, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {لا يَلِتْكُمْ}: لا يَنقُصُكم."}, "71865": {"num": 71865, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد-: {لا يَلِتْكُمْ} لا يظلمكم من أعمالكم شيئًا، {إنَّ اللَّهَ غَفُورٌ رَحِيمٌ} قال: غفور للذنوب الكثيرة، رحيم بعباده."}, "71868": {"num": 71868, "aya": 14, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {وإنْ تُطِيعُوا اللَّهَ ورَسُولَهُ}، قال: إن تصدّقوا إيمانكم بأعمالكم يَقْبَل ذلك منكم."}, "71792": {"num": 71792, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "قال عبد الله بن عباس: نَزَلتْ في ثابت بن قيس وقوله للرجل الذي لم يُفسح له: ابن فلانة. فقال رسول الله صلى الله عليه وسلم: «مَن الذاكر فلانة؟». فقام ثابت، فقال: أنا، يا رسول الله. فقال: «انظر في وجوه القوم». فنظر إليهم، فقال: «ما رأيتَ، يا ثابت؟». قال: رأيتُ أبيض، وأسود، وأحمر. قال: «فإنّك لا تفضلهم إلّا في الدّين والتقوى». فأنزل الله سبحانه في ثابت هذه الآية، وبالّذي لم يُفسِح له: {يا أيُّها الَّذِينَ آمَنُوا إذا قِيلَ لَكُمْ تَفَسَّحُوا فِي المَجالِسِ فافْسَحُوا} [المجادلة: 11] الآية."}, "71798": {"num": 71798, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق عثمان بن الأسود- قال: ما خَلَق الله الولد إلا مِن نُطفة الرجل والمرأة جميعًا؛ وذلك أن الله يقول: {إنّا خَلَقْناكُمْ مِن ذَكَرٍ وأُنْثى}."}, "71801": {"num": 71801, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جُبير- {وجَعَلْناكُمْ شُعُوبًا وقَبائِلَ}، قال: الشّعوب: القبائل العظام. والقبائل: البطون."}, "71802": {"num": 71802, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جُبير- قال: الشُّعوب: الجُمّاع، والقبائل: الأفخاذ التي يتعارفون بها."}, "71803": {"num": 71803, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {وجَعَلْناكُمْ شُعُوبًا وقَبائِلَ}، قال: القبائل: الأفخاذ، والشُّعوب: الجمهور مثل مُضَر."}, "71804": {"num": 71804, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- {وجَعَلْناكُمْ شُعُوبًا وقَبائِلَ}، قال: الشُّعوب: الأنساب."}, "71807": {"num": 71807, "aya": 13, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير -من طريق أبي حُصين- {وجَعَلْناكُمْ شُعُوبًا وقَبائِلَ}، قال: الشُّعوب: الأفخاذ، والقبائل: القبائل."}}, "n_athar": {"0": 10, "1": 22, "2": 18, "3": 15, "4": 17, "5": 8, "6": 18, "7": 10, "9": 31, "10": 6, "11": 39, "12": 54, "13": 46, "14": 34, "15": 3, "16": 1, "17": 14, "18": 1}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});